package com.meetspace.service; import com.meetspace.cache.EmployeeIndex; import com.meetspace.dto.EmployeeDtos.*; import com.meetspace.exception.ApiException; import com.meetspace.repository.EmployeeRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.UUID;
@Service public class EmployeeService{private final EmployeeRepository r;private final EmployeeIndex index;public EmployeeService(EmployeeRepository r,EmployeeIndex i){this.r=r;index=i;}public Profile me(UUID user){var p=r.byUser(user).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"EMPLOYEE_NOT_FOUND","Employee profile was not found"));if(!index.contains(p.id()))index.put(p);return index.get(p.id()).orElse(p);}public Profile update(UUID id,Update x){r.update(id,x);var p=me(id);index.put(p);return p;}}